UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Archaios is a melodic death metal band from Santo Domingo. It began in 1994 as Legion and took the name Archaios, which means “ancient”, in 2003.","type":"text"}]},{"type":"paragraph","content":[{"text":"As Legion","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Under its first name the band appeared with «Eterno Sufrimiento» and «Desperdida» on «Metal por un Tubo», a 1997 compilation CD issued by the magazine Radioactiva.","type":"text"}]},{"type":"paragraph","content":[{"text":"Albums","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Its first album, «Out of the Shadows», came out in 2005, and the second, «The Distant», on 11 November 2011 through «Dark Canvas Records». The international metal database Encyclopaedia Metallum lists its subjects as inner struggles, existentialism, vengeance and despair. Reviewing «The Distant» for Heavy Metal Tribune, a critic scored it 14 out of 20 and called it a modern update of the melodic death metal of Soilwork and In Flames, with guitar solos of an almost neo-classical feel; he said it was the first band from the Dominican Republic he had come across.","type":"text"}]},{"type":"paragraph","content":[{"text":"Abroad","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"The band’s tracks reached international compilations: «The Distant» on Metal Hammer’s «Global Metal Vol. 3» (2011), «Legions (In Remembrance Of...)» on Terrorizer’s «Fear Candy 102» (2012) and «The Distant» again on «Global Domination Vol. 1», a digital release of «No Remorse Records» in April 2014.","type":"text"}]},{"type":"paragraph","content":[{"text":"Members","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"The guitarist Eric Cruz has been in the band since 2003 and is the only current member listed. Past members include the guitarists JC Castillo, who played until his death in 2019, Joel Solano and Albert de Peña; the bassists Koresh and David Masalles, who has also played in","type":"text"},{"type":"artistReference","attrs":{"artistId":"ea2d1a26-e4d8-4daf-b487-52fe68faad36","displayText":"Soul of Death","occurrenceId":"942e3465-f8b3-41a8-98a6-9eda83c8eb1d"}},{"text":"; the drummers Johandy Ureña, Alfredo Baltrá and Silvio “El Chivo”, who has also played in «Necro»; and the vocalist Rubén Cruz.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In 2022 the metal site MetalSucks included Archaios in a list of fifteen bands from the Dominican Republic, and the international archives list it as active.","type":"text"}]}]}'::jsonb, revision = revision - 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'archaios' AND d.locale = 'en' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_en = 'Archaios is a melodic death metal band from Santo Domingo. It began in 1994 as Legion and took the name Archaios, which means “ancient”, in 2003.

**As Legion**

Under its first name the band appeared with «Eterno Sufrimiento» and «Desperdida» on «Metal por un Tubo», a 1997 compilation CD issued by the magazine Radioactiva.

**Albums**

Its first album, «Out of the Shadows», came out in 2005, and the second, «The Distant», on 11 November 2011 through «Dark Canvas Records». The international metal database Encyclopaedia Metallum lists its subjects as inner struggles, existentialism, vengeance and despair. Reviewing «The Distant» for Heavy Metal Tribune, a critic scored it 14 out of 20 and called it a modern update of the melodic death metal of Soilwork and In Flames, with guitar solos of an almost neo-classical feel; he said it was the first band from the Dominican Republic he had come across.

**Abroad**

The band’s tracks reached international compilations: «The Distant» on Metal Hammer’s «Global Metal Vol. 3» (2011), «Legions (In Remembrance Of...)» on Terrorizer’s «Fear Candy 102» (2012) and «The Distant» again on «Global Domination Vol. 1», a digital release of «No Remorse Records» in April 2014.

**Members**

The guitarist Eric Cruz has been in the band since 2003 and is the only current member listed. Past members include the guitarists JC Castillo, who played until his death in 2019, Joel Solano and Albert de Peña; the bassists Koresh and David Masalles, who has also played inSoul of Death; the drummers Johandy Ureña, Alfredo Baltrá and Silvio “El Chivo”, who has also played in «Necro»; and the vocalist Rubén Cruz.

**Legacy**

In 2022 the metal site MetalSucks included Archaios in a list of fifteen bands from the Dominican Republic, and the international archives list it as active.' WHERE slug = 'archaios';
