UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Archaios es una banda de death metal melódico de Santo Domingo. Empezó en 1994 como Legion y tomó el nombre de Archaios, que significa “antiguo”, en 2003.","type":"text"}]},{"type":"paragraph","content":[{"text":"Como Legion","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Con su primer nombre la banda apareció con «Eterno Sufrimiento» y «Desperdida» en «Metal por un Tubo», un CD recopilatorio de 1997 editado por la revista Radioactiva.","type":"text"}]},{"type":"paragraph","content":[{"text":"Discos","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Su primer álbum, «Out of the Shadows», salió en 2005 y el segundo, «The Distant», el 11 de noviembre de 2011 con «Dark Canvas Records». La base de datos internacional Encyclopaedia Metallum anota como temas las luchas interiores, el existencialismo, la venganza y la desesperación. Al reseñar «The Distant» para Heavy Metal Tribune, un crítico le puso 14 sobre 20 y lo describió como una actualización moderna del death metal melódico de Soilwork e In Flames, con solos de guitarra de aire casi neoclásico; dijo que era la primera banda dominicana con la que se topaba.","type":"text"}]},{"type":"paragraph","content":[{"text":"En el exterior","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Los temas de la banda llegaron a recopilatorios internacionales: «The Distant» en «Global Metal Vol. 3» de Metal Hammer (2011), «Legions (In Remembrance Of...)» en «Fear Candy 102» de Terrorizer (2012) y otra vez «The Distant» en «Global Domination Vol. 1», un lanzamiento digital de «No Remorse Records» de abril de 2014.","type":"text"}]},{"type":"paragraph","content":[{"text":"Integrantes","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"El guitarrista Eric Cruz está en la banda desde 2003 y es el único integrante actual que figura en las bases de datos. Entre los anteriores están los guitarristas JC Castillo, que tocó hasta su muerte en 2019, Joel Solano y Albert de Peña; los bajistas Koresh y David Masalles, que también ha tocado en","type":"text"},{"type":"artistReference","attrs":{"artistId":"ea2d1a26-e4d8-4daf-b487-52fe68faad36","displayText":"Soul of Death","occurrenceId":"58cef1cb-c373-4a00-87ce-9470dc9a87d8"}},{"text":"; los bateristas Johandy Ureña, Alfredo Baltrá y Silvio “El Chivo”, que también ha tocado en «Necro»; y el vocalista Rubén Cruz.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legado","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"En 2022 el sitio de metal MetalSucks incluyó a Archaios en una lista de quince bandas de República Dominicana, y los archivos internacionales la registran como activa.","type":"text"}]}]}'::jsonb, revision = revision - 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'archaios' AND d.locale = 'es' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_es = 'Archaios es una banda de death metal melódico de Santo Domingo. Empezó en 1994 como Legion y tomó el nombre de Archaios, que significa “antiguo”, en 2003.

**Como Legion**

Con su primer nombre la banda apareció con «Eterno Sufrimiento» y «Desperdida» en «Metal por un Tubo», un CD recopilatorio de 1997 editado por la revista Radioactiva.

**Discos**

Su primer álbum, «Out of the Shadows», salió en 2005 y el segundo, «The Distant», el 11 de noviembre de 2011 con «Dark Canvas Records». La base de datos internacional Encyclopaedia Metallum anota como temas las luchas interiores, el existencialismo, la venganza y la desesperación. Al reseñar «The Distant» para Heavy Metal Tribune, un crítico le puso 14 sobre 20 y lo describió como una actualización moderna del death metal melódico de Soilwork e In Flames, con solos de guitarra de aire casi neoclásico; dijo que era la primera banda dominicana con la que se topaba.

**En el exterior**

Los temas de la banda llegaron a recopilatorios internacionales: «The Distant» en «Global Metal Vol. 3» de Metal Hammer (2011), «Legions (In Remembrance Of...)» en «Fear Candy 102» de Terrorizer (2012) y otra vez «The Distant» en «Global Domination Vol. 1», un lanzamiento digital de «No Remorse Records» de abril de 2014.

**Integrantes**

El guitarrista Eric Cruz está en la banda desde 2003 y es el único integrante actual que figura en las bases de datos. Entre los anteriores están los guitarristas JC Castillo, que tocó hasta su muerte en 2019, Joel Solano y Albert de Peña; los bajistas Koresh y David Masalles, que también ha tocado enSoul of Death; los bateristas Johandy Ureña, Alfredo Baltrá y Silvio “El Chivo”, que también ha tocado en «Necro»; y el vocalista Rubén Cruz.

**Legado**

En 2022 el sitio de metal MetalSucks incluyó a Archaios en una lista de quince bandas de República Dominicana, y los archivos internacionales la registran como activa.' WHERE slug = 'archaios';
DELETE FROM editorial_entity_references WHERE editorial_document_id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'archaios' AND d.locale = 'es' AND d.document_type = 'artist_biography');
