UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Fefita la Grande, born Manuela Josefa Taveras Cabrera on 18 September 1943 in the village of El Orégano, near San José in San Ignacio de Sabaneta, Santiago Rodríguez, is a Dominican accordionist, singer and bandleader, and the foremost woman in the history of merengue típico. She took up the accordion as a small child at a time when the instrument was effectively closed to women, and has spent seven decades at the head of a music that belongs to the Cibao countryside. In 2016 she was given the Gran Soberano, the highest distinction Dominican arts confers.","type":"text"}]},{"type":"paragraph","content":[{"text":"Early years and the accordion","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"She was born to Eliseo \"Seíto\" de Jesús Cabrera Fernández and María Ana Taveras, and carries her mother''s surname first because her father did not recognise her at birth. She has one full sister, María Celeste, and six half-siblings on her father''s side. The accordion reached her in her father''s workshop while she was still very small, and she took the merengue típico pioneer ","type":"text"},{"type":"artistReference","attrs":{"artistId":"e07267a0-7f9d-4ef5-928c-d4ade7dc921e","displayText":"Guandulito","occurrenceId":"2d8ccfe9-7a21-4769-b815-ea9fd7969447"}},{"text":" as her model. By seven she was known around her community for her playing; by nine she was working parties with accordion, güira and tambora.","type":"text"}]},{"type":"paragraph","content":[{"text":"In about 1956, aged roughly twelve, she played for José Arismendy \"Petán\" Trujillo, who ran the state broadcaster La Voz Dominicana and was a brother of the dictator. He gave her a hundred pesos — the first money her playing earned her from outside her own district.","type":"text"}]},{"type":"paragraph","content":[{"text":"Three names","type":"text","marks":[{"type":"bold"}]