UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Rafael Zoilo Peralta, known to everyone in the music as El Pingüino, is a bass player in merengue típico. He is a sideman, and the people who remember him remember the bass itself.","type":"text"}]},{"type":"paragraph","content":[{"text":"The instrument","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Típico is accordion, tambora and güira, and when a bass arrived it arrived as an electric one, plugged in and locked to the tambora. He is remembered instead for playing an upright — a full acoustic double bass, standing, in a conjunto típico, which the players who saw it describe as something they had never seen in this music.","type":"text"}]},{"type":"paragraph","content":[{"text":"It is not a decorative difference. An upright answers the tambora differently: shorter decay, more air, less push. In a music whose whole engine is the argument between the accordion and the drum, changing what the bass does changes where the floor is.","type":"text"}]},{"type":"paragraph","content":[{"text":"Whose bands","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He is named in the conjunto of ","type":"text"},{"type":"artistReference","attrs":{"artistId":"9b15dfca-0f60-49b3-a139-100a5a329741","displayText":"Tatico Henríquez","occurrenceId":"0a4bbd2c-0af3-40df-b422-89341afe44e5"}},{"text":", the man who brought típico from Nagua into the capital and who added the bass and the guitar to a form that had done without both. Getting the bass chair in that band means being present at the moment the instrument entered the tradition at all.","type":"text"}]},{"type":"paragraph","content":[{"text":"He later worked with the Román family, on sides led by ","type":"text"},{"type":"artistReference","attrs":{"artistId":"7a92e4df-157c-49d9-9905-17ac0f740c4e","displayText":"Rafaelito Román","occurrenceId":"55915bb1-8889-4c60-9dec-24ee05176521"}},{"text":" — María Luisa, La Lisa, La Cama, La Cartera Vacía, La Cruz de Oro, Homenaje a Vidal — where the credit is written out under his full legal name. He also plays on El Ciego de Nagua’s Sabor a Caña, from 1978.","type":"text"}]},{"type":"paragraph","content":[{"text":"Nothing personal about him is written down: no date of birth, no town, no interview. What survives is a nickname, a run of credits and the memory of an unusual instrument.","type":"text"}]}]}'::jsonb, revision = revision - 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'rafael-zoilo-peralta' AND d.locale = 'en' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_en = 'Rafael Zoilo Peralta, known to everyone in the music as El Pingüino, is a bass player in merengue típico. He is a sideman, and the people who remember him remember the bass itself.

**The instrument**

Típico is accordion, tambora and güira, and when a bass arrived it arrived as an electric one, plugged in and locked to the tambora. He is remembered instead for playing an upright — a full acoustic double bass, standing, in a conjunto típico, which the players who saw it describe as something they had never seen in this music.

It is not a decorative difference. An upright answers the tambora differently: shorter decay, more air, less push. In a music whose whole engine is the argument between the accordion and the drum, changing what the bass does changes where the floor is.

**Whose bands**

He is named in the conjunto of Tatico Henríquez, the man who brought típico from Nagua into the capital and who added the bass and the guitar to a form that had done without both. Getting the bass chair in that band means being present at the moment the instrument entered the tradition at all.

He later worked with the Román family, on sides led by Rafaelito Román — María Luisa, La Lisa, La Cama, La Cartera Vacía, La Cruz de Oro, Homenaje a Vidal — where the credit is written out under his full legal name. He also plays on El Ciego de Nagua’s Sabor a Caña, from 1978.

Nothing personal about him is written down: no date of birth, no town, no interview. What survives is a nickname, a run of credits and the memory of an unusual instrument.' WHERE slug = 'rafael-zoilo-peralta';
