UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Manuel Jiménez —full name Manuel de Jesús Jiménez Ortega, born in the Sabana Grande section of Cotuí, Sánchez Ramírez, on 15 October 1952— is a Dominican singer-songwriter and, since 2020, a politician, best known for the ballad «Derroche».","type":"text"}]},{"type":"paragraph","content":[{"text":"«LUCUAM» and two educations","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He showed an early inclination for music, performing at school before moving to Santo Domingo. There he studied literature at the Universidad Autónoma de Santo Domingo and, at the same time, guitar and flute at the Academia Dominicana, joining and later directing the experimental music group «LUCUAM», where he developed as a composer of both romantic and socially conscious songs. He went on to earn a law degree at the Universidad Abierta Para Adultos.","type":"text"}]},{"type":"paragraph","content":[{"text":"«Derroche»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"«Derroche», released in 1993, became his best-known song and, by his own account, the one that has given him the greatest satisfaction as a composer. It has been recorded by more than twenty international artists, was the theme song of the Argentine film «Caballos Desbocados», and was the first Dominican song translated into Cantonese, besides being rendered in Portuguese, French, Danish and English. Asked once by Mariasela Álvarez which song by another songwriter he wished he had written, ","type":"text"},{"type":"artistReference","attrs":{"artistId":"10034596-47cb-46ba-9e80-9ea319a2c0df","displayText":"Juan Luis Guerra 4.40","occurrenceId":"e33c67d5-cfbc-440e-97ac-402c3a4ef6e1"}},{"text":" answered: «Derroche».","type":"text"}]},{"type":"paragraph","content":[{"text":"A song for every voice","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"His catalogue has traveled widely through other performers’ voices: «Quién no Sabe de Amor» through ","type":"text"},{"type":"artistReference","attrs":{"artistId":"080c0205-8b66-4f16-915e-1d867acf82cc","displayText":"Maridalia Hernández","occurrenceId":"88f1ddb8-bafe-4813-bec3-9829479f4f0f"}},{"text":", «Amor Casual» through ","type":"text"},{"type":"artistReference","attrs":{"artistId":"2bc36959-dcce-4e10-9ecf-2cd418eaa489","displayText":"Wilfrido Vargas","occurrenceId":"ceb1378a-922e-4277-8361-901d6507c892"}},{"text":", «Con Agua y Sal» through both ","type":"text"},{"type":"artistReference","attrs":{"artistId":"bc2289d0-ae94-48b5-8eb9-7f0ae18b845a","displayText":"Miriam Cruz","occurrenceId":"edda4302-8475-46ed-9097-0eb3471f9eb3"}},{"text":" and, decades later, ","type":"text"},{"type":"artistReference","attrs":{"artistId":"ae3c0afb-0e0a-4506-bbe6-a59c3c68bb1e","displayText":"Eddy Herrera","occurrenceId":"72524aec-9261-4296-b4e3-66f0080f343c"}},{"text":", «Dile Más» through ","type":"text"},{"type":"artistReference","attrs":{"artistId":"059a9e99-5d11-433e-97b9-9c35e57908f1","displayText":"Sergio Vargas","occurrenceId":"6e2cdf2b-747e-4093-9b6c-4c85e39fad6b"}},{"text":", and «En Cuarentena» through ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3422883e-7048-48af-bb03-c68c8c557ee4","displayText":"Los Hermanos Rosario","occurrenceId":"d0317b9f-49e2-47cf-8fec-183328c8ec72"}},{"text":". Abroad, the Colombian rapper Lisa M turned his «Súbeme el Radio» into the best-selling Latin rap single of 1993, winning an ASCAP Award in the United States. He represented the Dominican Republic four times at the OTI Song Festival, and two of his songs, «Guerembé» and «Santo Domingo Carnaval», were chosen as official Santo Domingo Carnival themes.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Jiménez entered politics at seventeen through the Movimiento Popular Dominicano, later serving on the Partido de la Liberación Dominicana’s central committee until his 2015 resignation and joining the Partido Revolucionario Moderno in 2019. He was a deputy in the National Congress and, in 2020, was elected mayor of Santo Domingo Este, a post he held until 2024, acknowledging along the way that his political career had cost him part of his musical following without ever making him abandon it.","type":"text"}]}]}'::jsonb, revision = revision - 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'manuel-jimenez' AND d.locale = 'en' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_en = 'Manuel Jiménez —full name Manuel de Jesús Jiménez Ortega, born in the Sabana Grande section of Cotuí, Sánchez Ramírez, on 15 October 1952— is a Dominican singer-songwriter and, since 2020, a politician, best known for the ballad «Derroche».

**«LUCUAM» and two educations**

He showed an early inclination for music, performing at school before moving to Santo Domingo. There he studied literature at the Universidad Autónoma de Santo Domingo and, at the same time, guitar and flute at the Academia Dominicana, joining and later directing the experimental music group «LUCUAM», where he developed as a composer of both romantic and socially conscious songs. He went on to earn a law degree at the Universidad Abierta Para Adultos.

**«Derroche»**

«Derroche», released in 1993, became his best-known song and, by his own account, the one that has given him the greatest satisfaction as a composer. It has been recorded by more than twenty international artists, was the theme song of the Argentine film «Caballos Desbocados», and was the first Dominican song translated into Cantonese, besides being rendered in Portuguese, French, Danish and English. Asked once by Mariasela Álvarez which song by another songwriter he wished he had written, Juan Luis Guerra 4.40 answered: «Derroche».

**A song for every voice**

His catalogue has traveled widely through other performers’ voices: «Quién no Sabe de Amor» through Maridalia Hernández, «Amor Casual» through Wilfrido Vargas, «Con Agua y Sal» through both Miriam Cruz and, decades later, Eddy Herrera, «Dile Más» through Sergio Vargas, and «En Cuarentena» through Los Hermanos Rosario. Abroad, the Colombian rapper Lisa M turned his «Súbeme el Radio» into the best-selling Latin rap single of 1993, winning an ASCAP Award in the United States. He represented the Dominican Republic four times at the OTI Song Festival, and two of his songs, «Guerembé» and «Santo Domingo Carnaval», were chosen as official Santo Domingo Carnival themes.

**Legacy**

Jiménez entered politics at seventeen through the Movimiento Popular Dominicano, later serving on the Partido de la Liberación Dominicana’s central committee until his 2015 resignation and joining the Partido Revolucionario Moderno in 2019. He was a deputy in the National Congress and, in 2020, was elected mayor of Santo Domingo Este, a post he held until 2024, acknowledging along the way that his political career had cost him part of his musical following without ever making him abandon it.' WHERE slug = 'manuel-jimenez';
