UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Milagros Quezada Borbón, conocida mundialmente como Milly Quezada, nació el 21 de mayo de 1955 en Santo Domingo, República Dominicana. Es una cantante, compositora y figura emblemática del merengue, reconocida como “La Reina del Merengue” por su impacto cultural, su trayectoria internacional y su papel pionero como mujer líder en un género históricamente dominado por hombres. Su carrera abarca más de cuatro décadas, con múltiples premios, giras internacionales y una influencia decisiva en la expansión del merengue a nivel global.","type":"text"},{"type":"hardBreak"},{"type":"hardBreak"},{"text":"Orígenes y formación","type":"text","marks":[{"type":"bold"}]},{"type":"hardBreak"},{"text":"Milly creció en una familia profundamente musical. Sus padres, Rafael Quezada y Consuelo Borbón, fomentaron un ambiente artístico donde ella y sus hermanos desarrollaron habilidades vocales y escénicas desde temprana edad. Durante su adolescencia emigró a Nueva York, donde la comunidad dominicana estaba en pleno crecimiento y donde el merengue comenzaba a consolidarse como símbolo de identidad cultural en la diáspora.","type":"text"},{"type":"hardBreak"},{"type":"hardBreak"},{"text":"En ese contexto, Milly estudió en el City College of New York, donde obtuvo una licenciatura en Comunicación y Medios. Su formación académica complementó su desarrollo artístico y le permitió manejar con destreza la proyección mediática de su carrera.","type":"text"},{"type":"hardBreak"},{"type":"hardBreak"},{"text":"Carrera musical","type":"text","marks":[{"type":"bold"}]},{"type":"hardBreak"},{"text":"La carrera de Milly Quezada inicia formalmente en la década de 1970 con el grupo Milly, Jocelyn y los Vecinos, integrado por ella, su hermana Jocelyn y músicos de la comunidad dominicana en Nueva York. El grupo se convirtió en un fenómeno cultural, llevando el merengue a escenarios internacionales y posicionándose como una de las primeras agrupaciones femeninas en el género.","type":"text"},{"type":"hardBreak"},{"type":"hardBreak"},{"text":"Canciones como “La Guacherna”, “Volvió Juanita”, “Tengo”, “Amanecemos Parrandeando” y “La Pringamosa” se convirtieron en himnos del merengue y en piezas esenciales de la identidad dominicana. Su estilo combinaba energía, carisma, arreglos modernos y una presencia escénica que rompía estereotipos de género dentro del merengue.","type":"text"},{"type":"hardBreak"},{"type":"hardBreak"},{"text":"Tras la muerte de su manager, Rafael Vázquez, en 1996, Milly regresó a República Dominicana y continuó su carrera como solista. Su etapa individual consolidó su título de “La Reina del Merengue”, con éxitos como “Lo Tengo Todo”, “Entre tu cuerpo y el mío”, “Porque me amaste”, “Para darte mi vida” y “Vive”.","type":"text"},{"type":"hardBreak"},{"type":"hardBreak"},{"text":"Ha colaborado con artistas como Juan Luis Guerra, Olga Tañón, Gilberto Santa Rosa, ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3f8bafec-e5ee-415d-8405-9551cceeeb9b","displayText":"Johnny Ventura","occurrenceId":"33f9dff0-ef1b-47d6-af43-1bc36d821b65"}},{"text":", Sergio Vargas, Héctor Acosta “El Torito”, Ilegales y otros, ampliando su alcance a géneros como salsa, balada y fusiones tropicales.","type":"text"},{"type":"hardBreak"},{"type":"hardBreak"},{"text":"Estilo musical e impacto cultural","type":"text"},{"type":"hardBreak"},{"text":"El estilo de Milly Quezada se caracteriza por una interpretación poderosa, un fraseo rítmico distintivo y una presencia escénica que combina fuerza, elegancia y cercanía con el público. Su trabajo ha sido fundamental para:","type":"text"},{"type":"hardBreak"},{"type":"hardBreak"},{"text":"- Internacionalizar el merengue en Estados Unidos, Europa y América Latina.  ","type":"text"},{"type":"hardBreak"},{"text":"- Abrir espacio para mujeres en un género dominado por agrupaciones masculinas.  ","type":"text"},{"type":"h